#!/usr/bin/env bash
set -euo pipefail
if [[ "${1:-}" == "--help" ]]; then
  printf '%s\n' \
    'Required: JDBC_URL (jdbc:postgresql://host:port/database), JDBC_CONFIG (absolute Java properties file),' \
    'PG_JDBC_JAR (absolute PostgreSQL JDBC driver jar), JDBC_POLICY_CODE (full allowed),' \
    'JDBC_PARTIAL_POLICY_CODE (PLAIN_PREFIX count=2 allowed), JDBC_DENIED_POLICY_CODE (existing unauthorized).' \
    'JDBC_CONFIG: user/password/sslmode/options etc. No dadp.* settings; mapping is generated by the probe.' \
    'PG17, UTF8, native KMS runtime provisioned by caller; dadp.dadp_encrypt(text,text)/dadp.dadp_decrypt(text) required.' \
    'Caller must grant CREATE SCHEMA and function execution; probe creates/drops a unique schema.' \
    'Optional: JAVA_HOME, WRAPPER_JAR, JDBC_PROBE_JAR. Build: bash scripts/build-jdbc-process-probe.sh' \
    'Success: JDBC_PLUGIN_PROBE_PASS and exit 0. Plugin JDBC mode only; no fake SQL/server.'
  exit 0
fi
[[ $# == 0 ]] || exit 2
: "${JDBC_URL:?required}" "${JDBC_CONFIG:?required}" "${PG_JDBC_JAR:?required}"
: "${JDBC_POLICY_CODE:?required}" "${JDBC_PARTIAL_POLICY_CODE:?required}" "${JDBC_DENIED_POLICY_CODE:?required}"
root="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd)"
wrapper="${WRAPPER_JAR:-$root/dadp-jdbc-wrapper/target/dadp-jdbc-wrapper-8.0.0-SNAPSHOT-all.jar}"
probe="${JDBC_PROBE_JAR:-$root/dadp-jdbc-wrapper/target/dadp-jdbc-wrapper-8.0.0-SNAPSHOT-jdbc-probe.jar}"
for file in "$JDBC_CONFIG" "$PG_JDBC_JAR" "$wrapper" "$probe"; do
  [[ "$file" == /* && -f "$file" && -r "$file" ]] || { printf 'Missing absolute readable input file\n' >&2; exit 2; }
done
exec "${JAVA_HOME:+$JAVA_HOME/bin/}java" -cp "$probe:$wrapper:$PG_JDBC_JAR" \
  com.dadp.jdbc.integration.JdbcProcessProbe "$JDBC_URL" "$JDBC_CONFIG" \
  "$JDBC_POLICY_CODE" "$JDBC_PARTIAL_POLICY_CODE" "$JDBC_DENIED_POLICY_CODE"
